/**
 * SLATE — how long each bank holds a card payment before it posts, how a
 * European bank dates an entry's value, and how long a card may hold back
 * the credit a payment frees.
 *
 * From research that read each bank's own terms (`probe/more/pending.jsonl`).
 * Generated by `probe/gen-pending.cjs`.
 */

export interface BankPending {
  /** Business days a debit card payment stays pending before it posts, and the bank's words. */
  pendingDays?: number;
  pendingWords?: string;
  /** The same for its credit card. */
  creditPendingDays?: number;
  /** A US bank's nightly posting order, in its words. */
  postingOrder?: string;
  /** How a European bank dates an entry's value apart from its booking, in its words. */
  valueDating?: string;
  /** Days a card may hold back the credit a payment frees, and its words. */
  paymentHoldDays?: number;
  paymentHoldWords?: string;
  source: string;
}

/** By bank id. */
export const PENDING: Readonly<Record<string, BankPending>> = JSON.parse("{\"us-chase\":{\"source\":\"Chase Deposit Account Agreement, effective June 14, 2026 (chase.com/content/dam/chase-ux/documents/personal/checking/deposit-account-agreement.pdf), Posting Order and Debit Card Authorizations and holds; Chase Cardmember Agreement COL00067 (chase.com/content/dam/chase-ux/feed/cmaonline/Chase/COL00067.pdf), Paying Us Back; chase.com/personal/credit-cards/education/basics/pending-transactions, read September 26, 2026\",\"pendingDays\":3,\"pendingWords\":\"When Chase approves a debit card purchase it holds that much of your available balance, generally for three business days. The merchant can take several days longer to collect, so the purchase may post after the hold has already dropped off.\",\"creditPendingDays\":5,\"postingOrder\":\"Each business night Chase first makes any adjustments from the day before and adds deposits. Then it takes out withdrawals, ATM and debit card transactions, checks, automatic payments, wires and real-time payments in the order of the date and time they were approved or showed as pending, with ties going largest to smallest. Items it has no time for post at the end of their day. Overdraft Protection transfers and similar items come next, largest to smallest, and fees come last.\",\"paymentHoldDays\":15,\"paymentHoldWords\":\"After you make a payment, it can take Chase up to 15 days to give you back the available credit the payment freed up.\"},\"us-bank-of-america\":{\"source\":\"Bank of America Deposit Agreement and Disclosures, effective May 15, 2026 (bankofamerica.com/salesservices/deposits/resources/deposit-agreements/), processing and posting order and debit card authorization holds; Example BankAmericard Credit Card Agreement (bankofamerica.com/content/documents/creditcard/bankamericard_english.pdf); bankofamerica.com/credit-cards/credit-card-payments-statements-faq/, read September 26, 2026\",\"pendingDays\":3,\"pendingWords\":\"When Bank of America approves a debit card purchase it may put a hold on that amount, and in most cases the hold ends three business days later or when the merchant collects, whichever comes first. Hotels and car rentals can be held longer, and if the merchant collects after the hold ends, the bank still pays it.\",\"postingOrder\":\"At the end of each business day Bank of America sorts items into groups and posts them group by group: backdated credits, then deposits and other credits, then backdated debits, then adjustments (each largest to smallest). Next come debits it has a date and time for, such as debit card purchases, ATM withdrawals, Zelle and wires, in date and time order with ties largest to smallest and undated ones last. Then checks in check-number order, then other electronic debits like ACH and bill payments largest to smallest, then fees, then Keep the Change transfers.\",\"paymentHoldWords\":\"The card agreement doesn’t set a hold on the credit a payment frees up. It only says a payment that doesn’t follow the payment instructions may take up to five days to be credited, and the payments FAQ says balances and available funds can take up to 2 business days to update after a payment.\"},\"us-wells-fargo\":{\"source\":\"Wells Fargo Deposit Account Agreement, effective July 28, 2026 (wellsfargo.com/assets/pdf/small-business/agreement.pdf, covers consumer and business), How we process and post transactions; wellsfargo.com/help/online-banking/activity-faqs/; Wells Fargo Active Cash Credit Card Account Agreement, June 23, 2026 (wellsfargo.com/credit-cards/agreements/active-cash-agreement/), read September 26, 2026\",\"pendingDays\":3,\"pendingWords\":\"If the merchant hasn’t asked Wells Fargo for payment within three business days, the bank usually releases the hold on a debit card purchase, though the merchant can still collect later. Car rentals, hotels, cash disbursements and international purchases can be held for up to 30 business days.\",\"postingOrder\":\"Each business night Wells Fargo first adds deposits received before the cutoff. Then it takes out items it already approved and can’t return, such as debit card purchases, ATM withdrawals, transfers, Bill Pay and cashed checks, sorted by the date and time they happened, with ties smallest to largest. Last come checks and preauthorized ACH payments, sorted by the date and time the bank received them, ties smallest to largest, with store-issued debit card ACH payments at the very end.\",\"paymentHoldWords\":\"Wells Fargo’s card agreement says it may hold back some of your available credit until your payment clears, but it doesn’t say for how many days.\"},\"us-citi\":{\"source\":\"Citibank Consumer Deposit Account Agreement, effective November 20, 2025 (citi.com/content/dam/cfs/mobile/assets/JRS/popups/ao/CDAA.pdf), 7.2.3 Posting Order and Authorizations; citi.com/banking/personal-banking-guide/basic-finance/how-to-remove-hold-on-bank-account-funds; Citi Card Agreement CMA_GenericADA-9 (citi.com/CRD/PDF/CMA/cardAgreement/CMA_GenericADA-9.pdf); citi.com/credit-cards/understanding-credit-cards/how-long-does-a-credit-card-payment-take-to-post, read September 26, 2026\",\"pendingDays\":7,\"pendingWords\":\"Citi says a debit card hold is typically lifted within five to seven business days, once the money has gone to the merchant. Its account agreement only says the hold stays until the purchase settles or Citi decides it probably won’t be processed.\",\"postingOrder\":\"Citi says it can post items in whatever order it chooses, but generally it first adds deposits made before the cutoff, then takes out its fees. Transactions that arrive in real time during the day, like ATM and teller withdrawals, debit card purchases, transfers, online bill payments and most ACH debits, come out as they happen if there’s enough money. Checks and any ACH debits not already taken during the day come out last, smallest to largest.\",\"paymentHoldWords\":\"Citi’s card agreement doesn’t say it holds back credit after a payment. Its guidance page only says some issuers hold payments for a while, especially large or new ones, before updating available credit.\"},\"us-capital-one\":{\"source\":\"Capital One 360 Checking Key account terms, revised February 2024 (ecm.capitalone.com/WCM/bank/pdfs/360-checking-pew.pdf); capitalone.com/bank/disclosures/checking-accounts/online-checking-account/ (May 20, 2026); capitalone.com/help-center/checking-savings/pending-transactions/; capitalone.com/help-center/credit-cards/card-pending-transactions/; capitalone.com/help-center/credit-cards/understanding-payment-holds/, read September 26, 2026\",\"pendingDays\":5,\"pendingWords\":\"Capital One says a pending debit card transaction lowers your available balance and can stay on the account for up to 5 days before it posts.\",\"creditPendingDays\":5,\"postingOrder\":\"PIN debit purchases, ATM transactions, withdrawals, Zelle transfers into Capital One and fees post as they come in during the day. Everything else posts in batches through the day in this order: ACH credits, checks presented for payment, signature debit card transactions, then scheduled items like Zelle to other banks, ACH debits and Mail a Check. Within each batch credits go first, then debits. Signature debit card transactions post in date and time order, scheduled Zelle, Mail a Check and Bill Pay go largest to smallest, and everything else goes smallest to largest.\",\"paymentHoldDays\":9,\"paymentHoldWords\":\"Sometimes Capital One needs time to confirm a payment from your bank before it adds the money back to your available credit. This payment hold lasts about 3 to 9 days, though it’s often quicker.\"},\"ca-rbc\":{\"source\":\"rbcroyalbank.com/credit-cards/cardholders.html; rbcroyalbank.com/credit-cards/cardholders/credit-card-transaction-help.html; rbcroyalbank.com/credit-cards/cardholders/frequently-asked-questions/payments.html, read September 26, 2026\",\"pendingWords\":\"RBC doesn’t publish a hold length for debit card purchases. For its credit cards it says most transactions stay authorized for 3 to 5 days, then move to posted once the merchant finishes on its end.\",\"creditPendingDays\":5},\"ca-td\":{\"source\":\"TD help: How and when do Pending Transactions get posted to my TD Credit Card? (td.intelliresponse.com id 7622); TD help: Why does TD place a hold on some TD Credit Card payments? (id 7442), read September 26, 2026\",\"pendingWords\":\"TD Canada Trust doesn’t publish a hold length for Access Card (debit) purchases. On its credit cards it says a pending transaction usually takes 3 to 5 business days to post, and available credit drops by the amount right away.\",\"creditPendingDays\":5,\"paymentHoldDays\":5,\"paymentHoldWords\":\"TD may hold a credit card payment that isn’t cash so it can verify where the money came from and that it cleared. The hold lasts up to 5 business days, counting the day of the payment.\"},\"ca-scotiabank\":{\"source\":\"help.scotiabank.com: How do pending transactions work?; help.scotiabank.com: When will the amount of my payments to my credit card or line of credit be available to use?, read September 26, 2026\",\"pendingDays\":7,\"pendingWords\":\"Pending transactions, including pre-authorizations (holds), can stay on your account for up to 7 days. Scotiabank gives one figure for all accounts and says days, not business days.\",\"creditPendingDays\":7,\"paymentHoldDays\":5,\"paymentHoldWords\":\"A payment to a Scotiabank credit card or line of credit may be held for up to 5 days before it shows in your available credit. Automated payments from another bank get the hold; paying from a Scotiabank account doesn’t.\"},\"ca-bmo\":{\"source\":\"bmo.com/en-ca/main/personal/credit-cards/credit-card-faqs (did not load); bmo.com/en-us/main/personal/checking-accounts/debit-mastercard (U.S., excluded), read September 26, 2026\",\"pendingWords\":\"BMO Canada’s own pages don’t give a figure: its Canadian help pages didn’t load when they were read. The 3- and 5-business-day debit holds that searches turn up are from BMO’s US site, so the game doesn’t use them.\"},\"ca-cibc\":{\"source\":\"cibc.com/en/personal-banking/credit-cards/real-time-credit-card-transactions.html; cibc.com/en/personal-banking/smart-advice/manage-your-shopping.html, read September 26, 2026\",\"pendingWords\":\"CIBC doesn’t publish a hold length for debit purchases in Canada. It says a merchant such as a gas station may put a pre-authorized hold that’s bigger than the sale, and you’re only charged the actual amount.\",\"creditPendingDays\":7,\"paymentHoldDays\":7,\"paymentHoldWords\":\"Only payments from a CIBC account show up in your available credit right away. A payment from another bank counts as unverified and usually posts within 5 to 7 business days while CIBC makes sure the money was there.\"},\"mx-bbva\":{\"source\":\"bbva.mx/educacion-financiera/banca-digital/cuenta-digital-que-es-saldo-retenido.html, read September 26, 2026\",\"pendingWords\":\"BBVA México says held money usually stays held for a few days until the merchant collects it, but in some cases approval can take up to a month. It gives no fixed number, and the app labels these charges \\\"in transit.\\\"\"},\"mx-santander\":{\"source\":\"santander.com.mx help pages: Consulta de saldos y movimientos, which couldn’t be opened, read September 26, 2026\",\"pendingWords\":\"Santander México’s own pages don’t give a figure: its help pages returned errors when they were read, and the figures searches turn up are from other sites.\"},\"mx-banamex\":{\"source\":\"Banamex official X account replies (x.com/banamex/status/1957557467576988115; x.com/banamex/status/2016897524640973004); banamex.com/es/centro-de-ayuda/tarjetas/operaciones-con-tarjeta-de-credito.htm, read September 26, 2026\",\"pendingDays\":9,\"pendingWords\":\"Banamex says an authorization that’s still pending or \\\"in process\\\" can stay that way from about 24 hours up to 9 business days on a debit card, and up to 15 business days on a credit card.\",\"creditPendingDays\":15,\"paymentHoldWords\":\"Banamex says card payments made at supermarkets, convenience stores and its ATMs are applied online and show up right away. It doesn’t say how long a payment from another bank takes.\"},\"mx-banorte\":{\"source\":\"banorte.com/Personal/Canales-Banorte/Horarios-y-tarifas.html; banorte.com Preguntas Frecuentes Tarjeta Universal (did not load), read September 26, 2026\",\"pendingWords\":\"Banorte’s own pages don’t say how long a pending charge is held: its FAQ page didn’t load when it was read.\",\"paymentHoldWords\":\"Payments made through Banorte Móvil and online banking show up immediately. Payments made by phone banking or at authorized agents show up between midnight and 10 p.m.; after that, they’re applied at 5 a.m. the next business day.\"},\"gb-barclays\":{\"source\":\"barclays.co.uk/help/payments/payment-information/not-debited; barclaycard.co.uk/personal/help/spending-transactions/pending-transactions; barclaycard.co.uk/personal/help/paying-bill/process-payment-online, read September 26, 2026\",\"pendingDays\":7,\"pendingWords\":\"A debit card purchase shows as pending and cuts your available balance, but it hasn’t left the account yet. That usually happens within seven days, though it can occasionally take longer.\",\"paymentHoldWords\":\"Barclaycard says a successful debit card payment to the card is credited to the account within two hours, and shows on the online statement within two working days. It doesn’t describe any hold on the freed credit.\"},\"gb-lloyds\":{\"source\":\"lloydsbank.com help-guidance/everyday-banking/statements/search-transactions and unrecognised-transactions (via search excerpts; pages returned errors when fetched); lloydsbank.com/credit-cards/ways-to-pay-your-credit-card.html, read September 26, 2026\",\"pendingDays\":7,\"pendingWords\":\"A pending transaction is money set aside for the retailer to collect. Merchants usually take it within a few days but it can take a few weeks, and if the retailer cancels or the payment fails it’s removed automatically, which should happen within a week.\"},\"gb-natwest\":{\"source\":\"natwest.com support pages/help-with-your-card/transactions/pending-transactions; natwest.com/current-accounts/bank-account-guides/pending-transactions.html; natwest.com support pages 'Are pending transactions included in the credit card balance', read September 26, 2026\",\"pendingDays\":4,\"pendingWords\":\"Retailers usually take a debit card payment within 4 working days for UK payments and up to 10 working days for international ones, and sometimes longer. A pending transaction can’t be canceled.\",\"creditPendingDays\":2,\"paymentHoldWords\":\"NatWest says a payment to the credit card should update the balance within 15 minutes in the app and Online Banking. Between 6:30 p.m. and 2:30 a.m. a cleared pending transaction may briefly be left out of the balance and available spend.\"},\"gb-hsbc\":{\"source\":\"hsbc.co.uk/financial-fitness/everyday-budgeting/understanding-your-balance; hsbc.co.uk/help/card-support/credit-card-repayment-options, read September 26, 2026\",\"pendingWords\":\"Debit card transactions can take several days to go through and show as pending until then. You can’t stop or cancel a pending transaction.\",\"paymentHoldWords\":\"HSBC says money paid to the card is normally credited immediately, subject to its standard checks, and the card balance updates the next working day. A Direct Debit is collected three days before the due date and shows as pending for those three days.\"},\"gb-santander\":{\"source\":\"retail.santander.co.uk Santander Help 'View pending authorisations' (help00000109); santander.co.uk/personal/support/credit-cards/your-credit-card-repayments, read September 26, 2026\",\"pendingWords\":\"Businesses often settle card payments at the end of the day or after a trading period, so a transaction might take a number of days to reach your statement. It shows as pending until it clears.\"},\"gb-nationwide\":{\"source\":\"nationwide.co.uk/help/payments/pending-transactions; nationwide.co.uk/credit-cards/help/check-card-balance, read September 26, 2026\",\"pendingDays\":7,\"pendingWords\":\"Pending transactions normally go into or out of the account within 7 days, and if the company hasn’t taken the money after 7 days Nationwide stops reserving it. Some current account payments can still arrive up to 180 days later, so it’s wise to keep the money there.\",\"creditPendingDays\":7},\"ie-aib\":{\"source\":\"aib.ie/help-and-guidance/aib-debit-card-faqs; aib.ie/help-and-guidance/about-my-balances; AIB Terms and Conditions for Current, Demand Deposit and Masterplan Accounts (Table 1, Table 3); AIB Personal Credit Card Terms and Conditions (conditions 8, 36-38), read September 26, 2026\",\"pendingDays\":3,\"pendingWords\":\"Pending debit card transactions generally post within a number of days, depending on the merchant, and contactless payments normally appear on the account within 2 to 3 days. Some card transactions don’t show as pending at all until the merchant tells AIB about them.\",\"valueDating\":\"AIB’s account terms give incoming electronic payments value, for interest purposes, on the business day it receives them (or the calendar day for transfers between AIB accounts and instant transfers), the same day the money becomes available. Outgoing instant transfers take value the calendar day they’re sent, though AIB may use the next or previous business day on a non-business day and refers you to the statement for the exact date. The terms don’t set a separate value date for card purchases, which are simply debited when they post.\",\"paymentHoldWords\":\"AIB gives payment value on the business day it receives a payment to the card, or the calendar day for an instant transfer, and money from an instant transfer is available to use that same calendar day. A merchant’s pre-authorization can reduce available credit until the merchant tells AIB to release it.\"},\"ie-bank-of-ireland\":{\"source\":\"bankofireland.com/help-centre/faq/do-i-owe-for-the-transactions-listed-in-in-progress-or-for-completed-transactions; Bank of Ireland Basic Bank Account Terms and Conditions 09.26 (clauses 14.5, 15.12, 15.14, 30.3); bankofireland.com/help-centre/faq/time-day-incoming-credits-come-current-account, read September 26, 2026\",\"pendingWords\":\"Card transactions under 'In progress' haven’t been processed by the seller yet, and in most cases they complete and post to the account in a few days. On a credit card they still reduce your available credit meanwhile.\",\"valueDating\":\"Bank of Ireland’s terms promise a record of every transaction showing its debit or credit value date. An incoming payment received on a banking day before cut-off, with no currency conversion, is credited the same banking day, and SEPA instant transfers are credited on any calendar day. Card purchases reduce the balance immediately but only reach the statement once fully processed; a lodged check shows on the statement the day it’s paid in even though it hasn’t cleared.\"},\"ie-ptsb\":{\"source\":\"ptsb.ie/legal-information/our-policies-other-important-information/business-days-and-cut-off-time (search excerpt); ptsb.ie help-and-support/help-with-banking/transacting-on-your-account and contactless-visa-debit-card-faq (search excerpts; the site itself couldn’t be opened), read September 26, 2026\",\"pendingWords\":\"Pending transactions are items authorized but not yet debited, such as a debit card purchase or a withdrawal at a non-PTSB ATM. Contactless transactions show in pending straight away.\",\"valueDating\":\"PTSB credits funds received before the cut-off on a business day to the account that day, and they start earning interest from the date received. Funds after cut-off count as the next business day. The cut-off is 6 p.m., or 5 p.m. for checks and 4 p.m. for international payments. PTSB’s full terms couldn’t be opened, so what its statement shows isn’t confirmed.\"},\"is-landsbankinn\":{\"source\":\"Skilmálar Landsbankans um færsluhirðingu (1546, from January 11, 2023), definition of authorization and the three-day submission clause; Almennir skilmálar um stofnun og notkun innlánsreikninga (1529, from November 13, 2017), read September 26, 2026\",\"pendingDays\":3,\"pendingWords\":\"An authorization sets the amount aside for as long as it’s valid, and merchants must send each card payment for settlement without delay, and no later than three days after it’s made. Those three days are calendar days, the deadline Landsbankinn sets merchants in its terms for taking cards; it publishes no figure for cardholders.\",\"valueDating\":\"Deposits earn interest from the day they’re paid in until the day they’re withdrawn, and the last interest day is the day before the withdrawal. So the value date is the booking day for money coming in, and the day before for money going out. Landsbankinn doesn’t set a separate value date for card payments.\"},\"is-arion\":{\"source\":\"arionbanki.is debit card pages (EN/IS); Almennir skilmálar innlánsreikninga Arion banka, March 16, 2017 (superseded), read September 26, 2026\",\"pendingWords\":\"Arion’s public pages and FAQs don’t say how long a card purchase stays pending, and its current card terms couldn’t be opened when they were read.\",\"valueDating\":\"Deposits generally earn interest from the moment the money is credited to the account, and the last interest day is the day before a withdrawal is debited. So incoming transfers are value-dated the day they arrive, and debits the day before they’re booked. This is from Arion’s deposit terms of March 2017, since replaced; the current version couldn’t be opened.\"},\"is-islandsbanki\":{\"source\":\"islandsbanki.is news 'Breytingar á debetkortagreiðslum' and 'Breytt sýn á debetkortafærslur' (2023); 'Kortaheimildir og páskar'; Skilmálar debetkorta EY-9092; Skilmálar kreditkorta EY-9096 (March 30, 2026) §8.4; Almennir skilmálar innlánsreikninga EY-9587 (April 22, 2024), read September 26, 2026\",\"pendingWords\":\"Since 2023 a debit card purchase isn’t taken from the account straight away. It shows as a pending transaction that reduces the available balance, and the money only actually leaves the account once the merchant settles its card terminal. The bank gives no number of days. When a prepaid card is closed after recent foreign use, the bank may keep the balance for 30 days to cover transactions merchants haven’t sent in yet.\",\"valueDating\":\"A deposit to a payment account earns interest from the moment the money is credited to the account, and the day before a debit is the last interest day on the money that leaves. Different rules can apply to deposits and withdrawals made on weekends and public holidays. Interest uses 30 days a month and 360 days a year.\",\"paymentHoldWords\":\"Paying the credit card bill before the due date, or paying into the card, frees up room on the limit. The bank doesn’t mention any delay before that room can be used.\"},\"fr-bnp-paribas\":{\"source\":\"BNP Paribas Convention de compte de dépôt, annexe contrat carte (April 2021) §6.4–6.5, §9; BNP Paribas Conditions et tarifs particuliers, 'Dates de valeur'; mabanque.bnpparibas 'Débit différé classic' (a search summary; the page couldn’t be opened); Légifrance CMF art. L133-14, read September 26, 2026\",\"pendingWords\":\"Card payments are debited once BNP Paribas receives them from the merchant’s bank through clearing, and it gives no number of days. On an immediate-debit card you need enough money in the account from the purchase until it’s debited. On a deferred-debit card, payments up to the 28th (or the next business day) are debited together on the last business day of the month, and they show in the meantime under upcoming operations. The deferred-debit dates are from a search summary of BNP Paribas’s page, which couldn’t be opened directly.\",\"valueDating\":\"The tariff brochure lists a value date for each kind of entry. Immediate-debit card payments are value-dated the day they’re executed, and deferred-debit card payments on the deferred debit business day. Incoming SEPA transfers are value-dated the settlement date. The one entry that runs later than booking is a check deposit on a French bank, at booking day plus one business day. French law (Code monétaire et financier L133-14) says a credit can’t be value-dated later than the business day the bank receives the funds, and a debit can’t be value-dated earlier than the day it’s debited.\"},\"fr-societe-generale\":{\"source\":\"SG Conditions Générales des cartes de débit (June 2026) e.3, g.4; SG Tarifs au 1er avril 2026 (sg-bt-2026.pdf) §3.4; MoneyVox 'Pourquoi un achat par carte bancaire met-il plusieurs jours…' (SG spokesperson); Légifrance CMF L133-14, read September 26, 2026\",\"pendingDays\":1,\"pendingWords\":\"The bank told MoneyVox that it books a card payment within 24 hours of receiving the clearing message, and shows it as 'being processed' in the meantime. Its card terms say a pre-authorized maximum amount (at a gas pump or hotel, say) counts against the card’s spending limits but doesn’t block the funds. Cards marked CRÉDIT are deferred-debit cards, debited once a month.\",\"valueDating\":\"Société Générale says it doesn’t apply value dates, except to check deposits: a euro check drawn on a French bank gets a value date one business day after collection, for interest purposes. French law (L133-14) also stops a credit from being value-dated later than the day the bank receives the funds.\"},\"fr-lcl\":{\"source\":\"lcl.fr FAQ 'SOS cartes'; LCL Carte Visa Cléo Dispositions Générales (December 7, 2023) §5.4; lcl.fr FAQ 'Gérer mes comptes'; Légifrance CMF L133-14, read September 26, 2026\",\"pendingWords\":\"Payments are debited from the account immediately unless a monthly deferred debit has been agreed. A hotel or car-rental booking can set an amount aside that counts against the monthly spending limit without being debited. Deferred-debit card payments are debited in one go on the last business day of the month; in 2026 statements close a day earlier, for example on January 29 and February 26. LCL doesn’t say how many days a purchase stays pending.\",\"valueDating\":\"None of LCL’s terms that were read give a value-date schedule; the only 2026 tariff extract available was four pages long. French law (L133-14) says a credit can’t be value-dated later than the business day the bank receives the funds, and a debit can’t be value-dated earlier than the day it’s debited.\"},\"fr-credit-agricole\":{\"source\":\"Crédit Agricole Île-de-France 'Principales conditions tarifaires' April 2026 (MoneyVox mirror of the bank’s brochure); credit-agricole.fr magazine 'Carte à débit différé' (search summary); Légifrance CMF L133-14, read September 26, 2026\",\"pendingWords\":\"Crédit Agricole says some merchants, like restaurants, gas stations or merchants abroad, don’t send card transactions right away, so they can appear several days later, and it suggests checking pending operations in online banking. It doesn’t give a number of days. Each of the 39 regional banks, Île-de-France included, sets its own deferred-debit cut-off and debit dates.\",\"valueDating\":\"The Île-de-France tariff brochure defines the value date as the date used to calculate overdraft interest. Cash deposits are value-dated the same day, and check deposits one business day after the transaction. It lists no separate value date for card payments or incoming transfers, which French law (L133-14) says can’t be value-dated later than the day the bank receives the funds.\"},\"fr-la-banque-postale\":{\"source\":\"La Banque Postale FAQ 'Que comprend la liste des opérations à venir'; LBP Tarifs particuliers au 1er janvier 2026; MoneyVox 'Pourquoi un achat par carte bancaire met-il plusieurs jours…' (LBP statement); Légifrance CMF L133-14, read September 26, 2026\",\"pendingDays\":2,\"pendingWords\":\"The bank told MoneyVox that an ordinary card payment in France, going through the standard clearing system, is cleared and received a day or two after the purchase, and that entries post to the online statement each evening around 10:30 to 11 p.m. Its help center says upcoming operations are shown only as a guide and may not go through, or may post on a different date.\",\"valueDating\":\"The 2026 tariff brochure only gives a value date for checks, which are credited the business day after the service center receives them. French law (L133-14) says card debits can’t be value-dated earlier than the day they’re debited, and incoming transfers no later than the day the funds arrive.\"},\"de-deutsche-bank\":{\"source\":\"Deutsche Bank, Bedingungen fuer Debitkarten (Stand January 2025), sec. 8 Sperrung eines verfuegbaren Geldbetrags; Preis- und Leistungsverzeichnis der Deutsche Bank AG (September 23, 2026), Wertstellungen and 2.3 Ueberweisungseingaenge, read September 26, 2026\",\"pendingWords\":\"Deutsche Bank’s debit card terms don’t give a day count. They say the bank may block an amount only when the merchant starts the payment and you’ve agreed to the exact amount, and that it releases the blocked amount without delay once it’s told the exact amount or receives the payment order.\",\"valueDating\":\"Statements carry a value date (Wertstellung). The price list sets debits (Belastungen) at the day of the debit and outgoing transfers at the day the bank executes them, and incoming transfers at the day the money reaches the bank, credited at most one business day after it arrives (instant transfers at once). Card payments follow the debit rule, so the value date is the day the charge is booked, not the day of purchase. Anything falling on a non-business day is value-dated the next business day. Deutsche Bank’s documents don’t cite section 675t BGB by name, but the rules match it.\"},\"de-commerzbank\":{\"source\":\"commerzbank.de/service/wie-sehe-ich-meinen-kontostand; commerzbank.de/privatkunden/wissen/ratgeber/grundwissen/banking/valuta-buchung-wertstellung; Commerzbank Preis- und Leistungsverzeichnis and Preisaushang (Stand September 15, 2026), read September 26, 2026\",\"pendingWords\":\"Commerzbank shows card payments and cash withdrawals in advance as “vorgemerkte Umsätze” in online banking and the app, and lists booked, outstanding and reserved amounts separately, but its pages don’t say how long a reservation lasts.\",\"valueDating\":\"Commerzbank’s own explainer says statements show both a booking date and a value date (Valuta), and the two needn’t match. Its example: a transfer executed on Friday, booked on Monday, carries a Tuesday value date; payments after the cut-off are processed the next business day. Its current price list leaves value dates to other documents and gives no rule for cards, and its pages don’t cite PSD2 or section 675t BGB.\"},\"de-postbank\":{\"source\":\"Postbank Preis- und Leistungsverzeichnis 923 959 000 07.26, sec. 10 Wertstellung; Postbank Bedingungen Debitkarten 923 933 018 01.25, sec. 8; Postbank Kreditkarten Besondere Bedingungen 923 933 017; postbank.de Umsaetze filtern help page, read September 26, 2026\",\"pendingWords\":\"Postbank says a card payment stays among the reserved transactions (vorgemerkte Umsätze) until it’s posted to the checking account, and that it already counts against the balance. Its debit card terms say a blocked amount is released without delay once the exact amount is known or the payment order arrives. Postbank’s own pages don’t confirm a number of days.\",\"valueDating\":\"Statements carry a value date. Postbank’s price list (sec. 10) value-dates incoming transfers on the day the money arrives, cash deposits on the deposit day, and outgoing transfers, direct debits and checks on the day the money leaves the account. The credit card is a charge card: each monthly statement falls due when it’s issued and is debited in one sum from the linked checking account. Postbank doesn’t cite PSD2 or section 675t BGB.\"},\"de-ing\":{\"source\":\"ing.de/wissen/vorgemerkte-umsaetze (Vorgemerkte Umsaetze beanstanden), read September 26, 2026\",\"pendingDays\":7,\"pendingWords\":\"ING says a VISA debit or girocard payment is reserved for the merchant when it’s approved, can’t be stopped or deleted, and already counts against the balance and the available limit. The reservation is removed when the final booking arrives or after 4 to 7 days.\",\"valueDating\":\"ING’s pages don’t give its value dates. They say a deposit that’s never collected, such as a hotel or rental-car hold, drops off the reserved list after a few days, and that foreign-currency and partly canceled payments can differ.\"},\"de-berliner-sparkasse\":{\"source\":\"Berliner Sparkasse Preis- und Leistungsverzeichnis July 15, 2026; Berliner Sparkasse Kreditkartenbedingungen (Fassung Maerz 2026), nos. 4, 7, 9; berliner-sparkasse.de Buchungszeiten FAQ, read September 26, 2026\",\"pendingWords\":\"The Sparkasse card terms don’t give a day count. They let the bank block an amount only when the merchant starts the payment and you’ve agreed to the exact amount, and they require the release without delay once the exact amount is known or the payment order arrives. On the credit card, purchases not yet on a statement already reduce what’s available.\",\"valueDating\":\"The price list says an incoming transfer is made available without delay once it reaches the Sparkasse’s account (an instant transfer within 10 seconds), and anything done on a Saturday, Sunday or holiday counts for value dating as done on the next business day. Internal transfers are processed around the clock but value-dated on the next business day. On the credit card, payments received are credited the same day as the charges, and the statement balance falls due at once and is debited from the linked checking account.\",\"paymentHoldWords\":\"The credit card terms say payments received are set off the same day as charges (\\\"taggleich\\\"), so there’s no stated hold; the credit comes back when the payment lands.\"},\"es-santander\":{\"source\":\"bancosantander.es card FAQs; wcm.bancosantander.es Documento de informacion precontractual Cuenta Santander (no hold or value-date terms for cards found), read September 26, 2026\"},\"es-bbva\":{\"source\":\"bbva.es card documents, which couldn’t be opened; bbva.es help pages searched, with no hold duration found, read September 26, 2026\"},\"es-caixabank\":{\"source\":\"CaixaBank Condiciones generales de tarjetas (c15B.pdf); caixabank.es FAQ Avanzar pago tarjeta de credito; caixabank.es FAQ Saldo retenido en mi cuenta, read September 26, 2026\",\"pendingWords\":\"CaixaBank’s card terms don’t give a hold period. They say debit-mode card payments are charged to the linked account immediately.\",\"valueDating\":\"Debit-mode card payments are charged immediately to the linked account with a value date of the day of the purchase, so booking and value date match. Credit cards pay off either the day after the monthly statement period ends (the default) or, on the 2-day plan, each purchase 48 hours after it’s made.\",\"paymentHoldWords\":\"Paying early (\\\"avance de pago\\\") frees the credit at once because it’s an online transfer, though the payment only shows on the card 24 hours later. On the 2-day plan the full limit is available again once the 48-hour debit clears.\"},\"es-sabadell\":{\"source\":\"Banco Sabadell Condiciones generales del contrato de tarjeta modelo BS06/21CGT, secs. 3.1, 8, 9 and special conditions; bancsabadell.com blog Saldo retenido, read September 26, 2026\",\"pendingWords\":\"Sabadell’s card terms say pre-authorizations, such as a reservation before a service or delivery, can place a temporary block on the card’s available credit or, for debit, on the account. They don’t say how long the block lasts; its blog says it’s released once the transaction is confirmed, usually within a few days.\",\"valueDating\":\"For debit cards, the terms say the charge hits the account when the payment order is received, which counts from the moment the merchant asks the bank for authorization. BS Card Mastercard debit purchases, though, are charged after settlement with a value date three calendar days after each purchase. On the Visa Oro Especial, amounts are debited on the 25th (or the business day before) with that same value date; on company credit cards it’s the 5th of the next month.\"},\"es-bankinter\":{\"source\":\"Bankinter Informacion precontractual Tarjeta Combo; Bankinter INE Tarjeta Visa Clasica; bankinter.com card FAQs, which couldn’t be opened; none of them gives hold periods or value dates; read September 26, 2026\"},\"jp-mufg\":{\"source\":\"MUFG FAQ 615 (faq01.bk.mufg.jp/faq/show/615); Mitsubishi UFJ NICOS FAQ 'When does my available credit come back after the debit?' (faq.cr.mufg.jp/mufgcard/detail?id=47), read September 26, 2026\",\"pendingDays\":0,\"pendingWords\":\"MUFG Debit takes the money at once, and when a purchase is canceled the refund depends on how the merchant processes it: up to about a month and a half for Visa debit and about two months for JCB debit. Until the merchant’s cancelation goes through, the amount can be taken twice, and the duplicate comes back within that same window.\",\"paymentHoldWords\":\"Mitsubishi UFJ NICOS restores shopping credit on the payment date itself. For cash advances and card loans it’s restored once NICOS confirms the payment, which is about four business days after the payment date and varies by bank.\"},\"jp-smbc\":{\"source\":\"SMBC Debit FAQ 'When does money come back after a return or cancellation?' (faq-debit.smbc-card.com); Sumitomo Mitsui Card 'Paying by transfer' (smbc-card.com/mem/oshiharai/rinji.jsp); Sumitomo Mitsui Card Hitotoki 'Statements and when they post' (smbc-card.com/mem/hitotoki/card_use/detailed_statement.jsp), read September 26, 2026\",\"pendingDays\":0,\"pendingWords\":\"SMBC Debit refunds a return or cancelation to the account around the day after it receives the merchant’s refund data. That data arrives in two to three days at the earliest and about two weeks at the latest.\",\"creditPendingDays\":3,\"paymentHoldDays\":2,\"paymentHoldWords\":\"Sumitomo Mitsui Card says a payment made by bank transfer takes up to two business days to show up in the available credit.\"},\"jp-mizuho\":{\"source\":\"Mizuho FAQ 7929 (faq.mizuhobank.co.jp/faq/show/7929); JCB FAQ 516 on credit after repayment (j-faq.jcb.co.jp/faq/show/516); JCB FAQ 293 on statement posting (j-faq.jcb.co.jp/faq/show/293), read September 26, 2026\",\"pendingDays\":0,\"pendingWords\":\"Once a cancelation or return is confirmed, JCB processes the refund for Mizuho JCB Debit, which can take about two weeks and sometimes longer.\",\"paymentHoldWords\":\"JCB, which issues Mizuho’s JCB cards, restores shopping credit on the payment date. An early repayment by bank transfer shows up about two business days after the transfer, and cash-advance payments take three to seven business days.\"},\"jp-resona\":{\"source\":\"Resona 'Visa debit cancellations and refunds' (resonabank.co.jp/kojin/visa_debit/modal/cancel.html, via search excerpt; the page couldn’t be opened); Resona Visa debit 'How payment works' (resonabank.co.jp/kojin/visa_debit/support/, via search excerpt), read September 26, 2026\",\"pendingDays\":0,\"pendingWords\":\"If a shop doesn’t send cancelation data, Resona’s Visa debit refunds the charge automatically about 45 days after the debit; the authorization lapses if no sales data arrives within 45 days. You can call to ask for an earlier refund, but it isn’t guaranteed.\"},\"jp-japan-post-bank\":{\"source\":\"Japan Post Bank FAQ 10989 on double debits (faq.jp-bank.japanpost.jp/faq_detail.html?id=10989); FAQ 10443 on refunds not received (faq_detail.html?id=10443), read September 26, 2026\",\"pendingDays\":0,\"pendingWords\":\"Japan Post Bank refunds a Yucho Debit return once it receives the merchant’s refund data, and when a return or cancelation leaves a double debit, the duplicate comes back later and can take up to about two months depending on the merchant.\"},\"kr-kb-kookmin\":{\"source\":\"KB Kookmin Card 'Payment methods' guide (card.kbcard.com/SVC/DVIEW/HSGMCXCRSCSC0103); KB Kookmin Card corporate check card page (mbiz.kbcard.com/CXEHMPGCD0004.cms, via search excerpt), read September 26, 2026\",\"pendingDays\":0,\"pendingWords\":\"A KB check card takes the money from the account the moment it’s approved, and KB says the sales slip is acquired two to three days after the card is used.\",\"paymentHoldDays\":1,\"paymentHoldWords\":\"KB Kookmin Card says that with instant-withdrawal payment, the card balance comes out of the linked account on the payment date and the credit limit can take up to one business day after the withdrawal to be restored.\"},\"kr-shinhan\":{\"source\":\"Shinhan Card 'Card usage guide' (shinhancard.com/pconts/html/helpdesk/useGuide/credit/MOBFM12502R01.html, via search excerpt: a same-day cancellation restores the limit at once, a later one once the sales cancellation completes, one to three days after the cancellation; the page itself wouldn’t render), read September 26, 2026\",\"pendingDays\":0,\"creditPendingDays\":3},\"kr-hana\":{\"source\":\"Hana Card 'Payment guide' (hanacard.co.kr/OSA15000000N.web), read September 26, 2026\",\"pendingDays\":0,\"paymentHoldWords\":\"Hana Card says that if the payment account is at a bank other than Hana Bank, the limit is restored after the payment is confirmed on the next business day. It names no wait for a Hana Bank account, which is where a Hana Bank customer pays from.\"},\"kr-nh\":{\"source\":\"NH NongHyup Card, NH Travlry check card product page (card.nonghyup.com/servlet/IpCc2021R.act?CD_WRS_SQNO=90010517), read September 26, 2026\",\"pendingDays\":0,\"pendingWords\":\"NH NongHyup Card refunds an approval canceled before the slip is acquired right away, and a cancelation after acquisition on the business day after the cancelation slip is acquired.\"},\"kr-kakaobank\":{\"source\":\"KakaoBank FAQ (card section), blog.kakaobank.com/82 and m.kakaobank.com FAQ, via search excerpt; pages didn’t render, read September 26, 2026\",\"pendingDays\":0,\"pendingWords\":\"KakaoBank refunds a check card payment canceled on the day of use that same day. A partial cancelation, or one made after the day of use, takes three to five business days from the cancelation, depending on the bank.\"},\"au-commbank\":{\"source\":\"commbank.com.au/support/disputing-a-transaction/dispute-pending-transaction.html; commbank.com.au support: How do pending transactions affect my balance?, read September 26, 2026\",\"pendingDays\":10,\"pendingWords\":\"A pending card transaction usually takes 3 to 5 business days to either go through or expire, but it can take up to 10 business days. If it expires, the money goes back into your available balance, though the business can still process it later and it’ll reappear.\"},\"au-westpac\":{\"source\":\"westpac.com.au/faq/pt-what-is-pending-transaction/; westpac.com.au/faq/pending-transactions/, read September 26, 2026\",\"pendingDays\":5,\"pendingWords\":\"When you pay by card, the amount is held as pending while Westpac waits for the merchant to confirm the payment, which usually takes up to 5 business days but can take longer. Hotels, car rentals and cruises can stay pending for as long as 30 days.\",\"creditPendingDays\":5},\"au-nab\":{\"source\":\"nab.com.au/help-support/transaction-dispute, read September 26, 2026\",\"pendingDays\":10,\"pendingWords\":\"A pending transaction usually takes 3 to 5 business days to either go through or drop off your transaction history. In extreme cases it can take up to 10 business days.\"},\"au-anz\":{\"source\":\"anz.com.au/plus/support/money-transactions/transaction-disputes/pending-transactions/; anz.com.au/support/business/internet-banking/getting-started/glossary/; anz.com.au/personal/bank-accounts/manage-my-accounts/faqs/, read September 26, 2026\",\"pendingDays\":7,\"pendingWords\":\"Pending card transactions usually take 5 to 7 business days to process, but ones tied to estimated or incremental authorizations, like hotel and car-rental holds, can take 16 days or longer. ANZ’s glossary says a merchant’s authorization stays on your account for up to six days.\"},\"nz-anz\":{\"source\":\"help.anz.co.nz a_id/310 Credit card transaction information (now redirects to anz.co.nz/banking-with-anz/ways-to-bank/guides/cards/; figures from a search summary), read September 26, 2026\",\"pendingDays\":5,\"pendingWords\":\"A hold that you don’t end up spending won’t be processed and drops off after a day or two. A card verification hold won’t be processed either and disappears from your account in five days.\",\"creditPendingDays\":2},\"nz-asb\":{\"source\":\"asb.co.nz/help/pending-transactions-on-my-credit-card.html; asb.co.nz/blog/2013/08/frequently-asked-questions-about-pending-transactions.html; asb.co.nz/help/when-are-credit-card-payments-processed.html (read through search summaries, as the pages couldn’t be opened), read September 26, 2026\",\"pendingDays\":5,\"pendingWords\":\"Pending transactions are usually processed overnight, but some take 4 to 5 days. Accommodation, rental car and cruise transactions can be held for up to 30 days.\",\"creditPendingDays\":5,\"paymentHoldWords\":\"A credit card payment made before 8:30 p.m. is processed overnight (after 8:30 p.m., the next night) and shows as pending until then; ASB doesn’t describe holding back the freed credit after that.\"},\"nz-bnz\":{\"source\":\"bnz.co.nz/support/credit-cards/security/pending-transactions (covers credit cards and Flexi Debit Visa), read September 26, 2026\",\"pendingDays\":3,\"pendingWords\":\"The final transaction usually goes through within 2 to 3 business days. A hold drops off once the final transaction is processed, or within 2 to 3 business days, and the same goes for a $1 card check.\",\"creditPendingDays\":3},\"nz-westpac\":{\"source\":\"westpac.co.nz/personal/life-money/managing-your-money/understanding-pending-transactions/; westpac.co.nz/help/why-hasnt-my-payment-appeared-on-my-credit-card-balance/ (the pages couldn’t be opened, so they were read through search summaries), read September 26, 2026\",\"pendingDays\":10,\"pendingWords\":\"Electronic transactions are usually processed within 3 to 10 days, and manual ones can take up to 30 days. Pre-authorization holds from hotels, gas stations and booking agents can take a few days to disappear.\",\"paymentHoldWords\":\"Payments are normally credited the day they’re processed, and a Westpac One transfer is applied on the day you make it. Any delay is backdated to the processing date for interest.\"},\"nz-kiwibank\":{\"source\":\"kiwibank.co.nz/help/cards/dispute-a-transaction/; kiwibank.co.nz/documents/guide-view-accounts-balances/ (the pages didn’t load, so they were read through search summaries), read September 26, 2026\",\"pendingWords\":\"Kiwibank says a pending transaction can’t be disputed or reversed until it finishes processing, but it doesn’t give a number of days.\",\"paymentHoldDays\":2,\"paymentHoldWords\":\"A payment to a Kiwibank credit card updates the available balance automatically, but if it’s made outside ordinary business hours the update to the available or owing balance can be delayed by up to two business days.\"}}");
